    static class ClosedParts
    {
        public sealed class Drawing
        {
            public int Width;
            public int Height;
            public string Base64;

            /// Its pixels, or null where they are not Width * Height * 4 bytes.
            public byte[] GetRgba()
            {
                var data = Convert.FromBase64String(Base64);
                return data.Length == Width * Height * 4 ? data : null;
            }
        }

